#include "binary_search_tree.h"

#include <algorithm>
#include <cassert>
#include <cstdint>
#include <iterator>
#include <memory>
#include <random>
#include <string>
#include <type_traits>
#include <vector>

int main() {
    using tree_type = binary_search_tree::binary_tree<int>;
    static_assert(std::is_same<std::iterator_traits<tree_type::iterator>::iterator_category,
                               std::bidirectional_iterator_tag>::value, "iterator category");
    static_assert(std::is_same<std::iterator_traits<tree_type::iterator>::value_type, int>::value, "value type");
    static_assert(std::is_same<std::iterator_traits<tree_type::iterator>::reference, int&>::value, "reference");

    std::mt19937 rng(20261126);
    for (int trial = 0; trial < 200; ++trial) {
        std::vector<int> values;
        const int count = 1 + static_cast<int>(rng() % 120);
        for (int i = 0; i < count; ++i) {
            values.push_back(static_cast<int>(rng() % 41) - 20);
        }

        tree_type tree(values.front());
        for (std::size_t i = 1; i < values.size(); ++i) {
            tree.insert(values[i]);
        }

        std::vector<int> expected = values;
        std::sort(expected.begin(), expected.end());
        std::vector<int> forward(tree.begin(), tree.end());
        assert(forward == expected);
        assert(static_cast<std::size_t>(std::distance(tree.begin(), tree.end())) == expected.size());

        std::vector<int> backward;
        for (auto it = tree.end(); it != tree.begin();) {
            --it;
            backward.push_back(*it);
        }
        std::reverse(backward.begin(), backward.end());
        assert(backward == expected);

        for (int value : expected) {
            assert(tree.contains(value));
        }
        for (int value = -25; value <= 25; ++value) {
            assert(tree.contains(value) == std::binary_search(expected.begin(), expected.end(), value));
        }

        auto it = tree.begin();
        auto previous = it++;
        assert(*previous == expected.front());
        assert(*it == expected[1]);
        auto current = it--;
        assert(*current == expected[1]);
        assert(*it == expected.front());

        const tree_type& const_tree = tree;
        assert(const_tree.begin() == tree.cbegin());
        assert(tree.begin() != tree.cend());
        std::vector<int> const_forward(const_tree.begin(), const_tree.end());
        assert(const_forward == expected);

        while (it != tree.end()) {
            ++it;
        }
        assert(it == tree.cend());

        tree_type copy = tree;
        std::vector<int> copy_forward(copy.begin(), copy.end());
        assert(copy_forward == expected);
        copy.insert(1000);
        assert(!tree.contains(1000));

        tree_type assigned(12345);
        assigned = tree;
        std::vector<int> assigned_forward(assigned.begin(), assigned.end());
        assert(assigned_forward == expected);

        tree_type moved(std::move(copy));
        std::vector<int> moved_forward(moved.begin(), moved.end());
        assert(!moved_forward.empty());
    }

    binary_search_tree::binary_tree<std::string> words("m");
    for (const auto& word : {"z", "a", "m", "b", "y", "a"}) {
        words.insert(word);
    }
    const std::vector<std::string> expected_words{"a", "a", "b", "m", "m", "y", "z"};
    std::vector<std::string> actual_words(words.begin(), words.end());
    assert(actual_words == expected_words);
    assert(words.contains("a"));
    assert(!words.contains("c"));

    return 0;
}
